import{_ as t,o as a,c as i,X as n}from"./chunks/framework.6lxT3esk.js";const k=JSON.parse('{"title":"Installation","titleTemplate":":title · PyCellPack","description":"","frontmatter":{},"headers":[],"relativePath":"python/docs/installation.md","filePath":"python/docs/installation.md"}'),s={name:"python/docs/installation.md"};function l(o,e,r,p,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Install the <a href="https://pypi.org/project/pycellpack/" target="_blank" rel="noreferrer">published <code>pycellpack</code> package from PyPI</a> in your Python project:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pycellpack</span></span></code></pre></div><p>For a new project, run <code>uv init cellpack-demo</code> and <code>cd cellpack-demo</code> first. The distribution name and import name are both <code>pycellpack</code>.</p><p>Version 0.1.0 provides Linux wheels for CPython 3.10–3.15 on x86-64 and AArch64 with glibc 2.28 or newer. Installing a matching wheel requires no Rust toolchain or CellPack checkout. The source distribution requires a compatible Rust/native build environment if no wheel matches your platform.</p><p>Verify the installation in the project environment:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import pycellpack; from importlib.metadata import version; print(version(&#39;pycellpack&#39;))&quot;</span></span></code></pre></div><h2 id="dependencies-and-integrations" tabindex="-1">Dependencies and integrations <a class="header-anchor" href="#dependencies-and-integrations" aria-label="Permalink to &quot;Dependencies and integrations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Dependencies</th></tr></thead><tbody><tr><td>Core package</td><td>Python, NumPy and typing-extensions; installed automatically</td></tr><tr><td>SciPy conveniences</td><td>The <code>scipy</code> extra</td></tr><tr><td>AnnData / H5AD / H5CP</td><td>The <code>anndata</code> extra and its declared Python-version constraints</td></tr><tr><td>Training Tensor batches</td><td>Install PyTorch separately for the target environment</td></tr><tr><td>Native process/access functions</td><td>A compatible native compiler or a prepared shared library; Numba where used</td></tr></tbody></table><p>The current package declares Python <code>&gt;=3.10,&lt;3.16</code>. The AnnData extra is pinned separately and requires Python 3.12 or newer. Importing <code>pycellpack</code> does not import SciPy, AnnData, h5py, pandas, PyTorch, or Numba; integrations load dependencies when used.</p><p>Select the needed extras from PyPI:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pycellpack[scipy]&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pycellpack[anndata]&#39;</span></span></code></pre></div><p>The <code>anndata</code> extra already includes SciPy and h5py. PyTorch is installed separately for your CPU or CUDA environment; it is not a PyCellPack extra.</p><p>Continue with the <a href="/CellPack/python/docs/quickstart.html">matrix quickstart</a> or <a href="/CellPack/python/training/">training examples</a>.</p>`,14)])])}const y=t(s,[["render",l]]);export{k as __pageData,y as default};
